GO
SET QUOTED_IDENTIFIER ON
GO
create FUNCTION [dbo].[GetAssetUrlById]
(	
	@AssetID bigint
)
RETURNS TABLE 
AS
RETURN 
(
	
	-- Add the SELECT statement with parameter references here
	SELECT CASE A.Object
		WHEN 'Artifact' THEN 'artifact/' +  + CAST(T.ObjectID as varchar) + '/' + CAST(A.ObjectID as varchar)
		WHEN 'ReferenceItem' THEN 'reference/' +  + CAST(T.ObjectID as varchar)-- + '/' +  + CAST(A.ObjectID as varchar)
		WHEN 'FusionAttribute' THEN 'fusion/fusionattribute/' + CAST(T.ObjectID as varchar) + '/' + CAST(A.ObjectID as varchar)		
		WHEN 'Fusion' THEN 'fusion/' + CAST(T.ObjectID as varchar) + '/' + + CAST(A.ObjectID as varchar)
		WHEN 'Group' THEN 'group/' + CAST(A.ObjectID as varchar)	
		WHEN 'Policy' THEN 'policy/' + CAST(T.ObjectID as varchar(15)) + '/id/' + CAST(A.ObjectID as varchar)
		WHEN 'Resource' THEN 'resource/' + CAST(A.ObjectID as varchar)
		WHEN 'Rule' THEN 'quality/rule/' + CAST(T.ObjectID as varchar) + '/' + CAST(A.ObjectID as varchar)
		WHEN 'Taxonomy' THEN 'model/' + CAST(T.ObjectID as varchar) + '/id/' + CAST(A.ObjectID as varchar)
	end as Url
	from 
		Asset A
		inner join AssetType T on T.ID = A.AssetTypeID
	where A.ID = @AssetID
)

GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create FUNCTION [dbo].[GetAssetTypeUrlById]
(	
	@AssetTypeID int
)
RETURNS TABLE 
AS
RETURN 
(
	-- Add the SELECT statement with parameter references here
	SELECT CASE T.Object
		WHEN 'ArtifactType' THEN 'artifact/' + CAST(T.ObjectID as varchar)
		WHEN 'ReferenceItem' THEN 'reference/' +  + CAST(T.ObjectID as varchar)-- + '/' +  + CAST(@ObjectID as varchar)
		WHEN 'ReferenceItemType' THEN 'reference/' + CAST(T.ObjectID as varchar)
		WHEN 'FusionType' THEN 'fusion/' + CAST(T.ObjectID as varchar)
		WHEN 'PolicyType' THEN 'policy/' + CAST(T.ObjectID as varchar) + '/structure'		
		WHEN 'ResourceType' THEN 'resource/list/' + CAST(T.ObjectID as varchar)
		WHEN 'RuleType' THEN 'quality/rule/' + CAST(T.ObjectID as varchar)	
		WHEN 'TaxonomyType' THEN 'model/' + CAST(T.ObjectID as varchar) + '/structure'	
	end as Url
	from AssetType T
	where T.ID = @AssetTypeID
)

