CREATE VIEW [dbo].[FieldTypeWithRelation]
AS
	SELECT	T.ID,
			T.Name,
			T.FriendlyName,
			T.Category,
			T.Description,
			T.DisplayDescription,
			T.FormDescription,
			T.ValidationDescription,
			T.Type,
			T.LookupObjectType,
			T.LookupObjectID ,
			T.LookupDisplayFormat,
			T.Length,
			T.MinimumLength,
			T.MaximumLength,
			T.Pattern,
			T.[Object],
			T.ObjectID,
			D.Name as ObjectName,
			T.IsDisplayable,
			T.IsEditable,
			T.IsListable,
			T.IsRequired,
			T.SortOrder,
			T.DefaultValue
	FROM	FieldType T
			inner join (
				select Name, Object, ObjectID from AssetType
				union all
				select ITypeName.Name as Name, 'IntersectType' as Object, ID as ObjectID from IntersectType IT
				cross apply dbo.GetIntersectTypeNames(IT.ID) ITypeName
			) D on D.[Object] = T.[Object] and D.ObjectID = T.ObjectID
