CREATE VIEW [dbo].[FollowDetail]
AS
	with ArtifactTypes as
	(
	select	ID as FollowID,
			ObjectType as [Object],
			ObjectID,
			ResourceID,
			1 as HardFollow
	from	Follow
	where	ObjectType = 'ArtifactType' and FollowTypeID = 3
	union all
	select	P.ID as FollowID,
			cast('Artifact' as varchar(50)) as [Object],
			C.ID as ObjectID,
			P.ResourceID,
			0 as HardFollow
	from	Artifact C
			inner join Follow P on P.ObjectType = 'ArtifactType' and P.ObjectID = C.ArtifactTypeID and P.FollowTypeID = 3
	),
	DomainTypes as
	(
	select	ID as FollowID,
			ObjectType as [Object],
			ObjectID,
			ResourceID,
			1 as HardFollow
	from	Follow
	where	ObjectType = 'ReferenceItemType' and FollowTypeID = 3
	),
	Groups as
	(
	select	ID as FollowID,
			ObjectType as [Object],
			ObjectID,
			ResourceID,
			1 as HardFollow
	from	Follow
	where	ObjectType = 'Group' and ObjectID = 0 and FollowTypeID = 3
	union all
	select	P.ID as FollowID,
			P.ObjectType as [Object],
			C.ID as ObjectID,
			P.ResourceID,
			0 as HardFollow
	from	[Group] C
			inner join Follow P on P.ObjectType = 'Group' and P.ObjectID = 0 and P.FollowTypeID = 3
	),
	PolicyTypes as
	(
	select	ID as FollowID,
			ObjectType as [Object],
			ObjectID,
			ResourceID,
			1 as HardFollow
	from	Follow
	where	ObjectType = 'PolicyType' and FollowTypeID = 3
	union all
	select	P.ID as FollowID,
			cast('Policy' as varchar(50)) as [Object],
			C.ID as ObjectID,
			P.ResourceID,
			0 as HardFollow
	from	Policy C
			inner join Follow P on P.ObjectType = 'PolicyType' and P.ObjectID = C.PolicyTypeID and P.FollowTypeID = 3
	),
	PolicyParents as
	(
	select	F.ID as FollowID,
			T.ID,
			T.ParentID,
			F.ResourceID,
			1 as HardFollow
	from	Policy T
			inner join Follow F on F.ObjectType = 'Policy' and F.ObjectID = T.ID and F.FollowTypeID = 3
	union all
	select	P.FollowID,
			C.ID,
			C.ParentID,
			P.ResourceID,
			0 as HardFollow
	from	Policy C
			inner join PolicyParents P on P.ID = C.ParentID
	),
	Resources as
	(
	select	ID as FollowID,
			ObjectType as [Object],
			ObjectID,
			ResourceID,
			1 as HardFollow
	from	Follow
	where	ObjectType = 'ResourceType' and FollowTypeID = 3
	union all
	select	P.ID as FollowID,
			cast('Resource' as varchar(50)) as [Object],
			C.ResourceID as ObjectID,
			P.ResourceID,
			0 as HardFollow
	from	reporting.Global_Resource C
			inner join Follow P on P.ObjectType = 'ResourceType' and P.FollowTypeID = 3
	where	C.ResourceID > 0
	),
	TaxonomyParents as
	(
	select	F.ID as FollowID,
			T.ID,
			T.ParentID,
			F.ResourceID,
			1 as HardFollow
	from	Taxonomy T
			inner join Follow F on F.ObjectType = 'Taxonomy' and F.ObjectID = T.ID and F.FollowTypeID = 3
	union all
	select	P.FollowID,
			C.ID,
			C.ParentID,
			P.ResourceID,
			0 as HardFollow
	from	Taxonomy C
			inner join TaxonomyParents P on P.ID = C.ParentID
	)

	SELECT		F.FollowID,
				F.ResourceID,
				R.Email,
				R.Email as FollowerEmail,
				R.FirstName + ' ' + R.LastName as FollowerName,
				R.FirstName as FollowerFirstName,
				R.LastName as FollowerLastName,
				'Resource' as FollowerObjectType,
				F.ResourceID as FollowerObjectID,
				dbo.GenerateAssetUrl((select ID from Asset where Object ='Resource' and ObjectID = F.ResourceID)) as FollowerUrl,
				F.ObjectID,
				F.[Object] as ObjectType,
				O.ObjectID as ID,
				O.Name,
				O.TextPath,
				O.Description,
				O.ParentID,
				O.Parent as ParentType,
				O.Url,
				O.ObjectTypeID as TypeID,
				O.ObjectType as [Type],
				case O.ObjectType
					when 'ResourceType' then 'User'
					when 'Group' then 'Group'
					else O.ObjectTypeName
				end as [TypeName],
				O.IconBackColor,
				O.IconForeColor,
				O.IconText,
				0 AS OpenEventCount,
				0 as CurrentScore,
				cast(F.HardFollow as bit) as HardFollow
	FROM		(
				select	FollowID,
						[Object], 
						ObjectID, 
						ResourceID, 
						HardFollow 
				from	ArtifactTypes
				union
				select	FollowID,
						[Object], 
						ObjectID, 
						ResourceID, 
						HardFollow 
				from	DomainTypes
				union
				select	FollowID,
						[Object], 
						ObjectID, 
						ResourceID, 
						HardFollow 
				from	Groups
				union
				select	FollowID,
						[Object], 
						ObjectID, 
						ResourceID, 
						HardFollow 
				from	PolicyTypes
				union
				select	FollowID,
						'Policy', 
						ID as ObjectID, 
						ResourceID, 
						HardFollow 
				from	PolicyParents
				union
				select	FollowID,
						[Object], 
						ObjectID, 
						ResourceID, 
						HardFollow 
				from	Resources
				union
				select	FollowID,
						'Taxonomy' as [Object], 
						ID as ObjectID, 
						ResourceID, 
						HardFollow 
				from	TaxonomyParents
				union
				select	ID as FollowID,
						ObjectType as [Object], 
						ObjectID, 
						ResourceID, 
						1 as HardFollow 
				from	Follow
				where	FollowTypeID = 1	
				) F
				inner join reporting.Global_Resource R on R.ResourceID = F.ResourceID
				inner join cache.ObjectDetails O on O.[Object] = F.[Object] and O.ObjectID = F.ObjectID

GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE view [dbo].[Relationship]
as
	select	R.IntersectTypeID,
			R.ID as IntersectID,
			2 as Classification,
			null as Description,
			'' as [Role],
			0 as SourceIntersectTypeNodeID,
			R.Subject as SourceObjectType,
			R.SubjectID as SourceObjectID,
			R.SubjectName as SourceName, 
			'' as SourceParent,
			0 as SourceParentID,
			'' as SourceParentName,
			R.SubjectTypeID as SourceTypeID,
			R.SubjectType as SourceType,
			R.SubjectTypeName as SourceTypeName,
			R.[SubjectUrl] as SourceUrl,
			0 as TargetIntersectTypeNodeID,
			R.Object as TargetObjectType,
			R.ObjectID as TargetObjectID,
			R.ObjectName as TargetName,
			'' as TargetParent,
			0 as TargetParentID,
			'' as TargetParentName,
			R.ObjectTypeID as TargetTypeID,
			R.ObjectType as TargetType,
			R.ObjectTypeName as TargetTypeName,
			R.[ObjectUrl] as TargetUrl,
			TR.[Exists] as HasTechnicalRelationships
	from	IntersectDetail R
			cross apply (
						select	case 
									when count(1) > 0 then cast(1 as bit) 
									else cast(0 as bit) 
								end as [Exists]
						from	[Intersect]
						where	Subject = 'Intersect' and SubjectID = R.ID
						) TR
