CREATE PROCEDURE [dbo].[GetAssetHierarchy]
  ( @ID int,
    @Type varchar(50) )
	AS
	Begin
	-- declare  @ID int =2430947 ;--4832;-- 16113;
	--declare @Type varchar(50) ='FusionAttribute';--'Taxonomy'; --'Artifact'
    if @Type = 'Artifact'  
	  begin  
	   with Sub as (  
		select O.ID,  
		  O.ParentID,  
		  D.TextPath as [Path],  
		  D.TypeName as LevelName,  
		  D.Url as Url,  
		  1 as [Level]  
		from Artifact O  
		 cross apply [utility].[ObjectDetail](@Type,O.ID) as D  
		where O.ID = @ID  
		union all  
		select O.ID,  
		  O.ParentID,  
		  D.TextPath as [Path], 
		  D.TypeName as LevelName,
		  D.Url as Url,   
		  C.[Level] + 1 as [Level]  
		from Artifact O  
		  inner join Sub as C on C.ParentID = O.ID  
		   cross apply [utility].[ObjectDetail](@Type,O.ID) as D  
	   )  
	  select ID, ParentID,[Path],LevelName,Url,rank() over (Order by Level desc) as [Level] from Sub;
  end
  else if @Type = 'Taxonomy'  
  begin
	   with Sub as (  
		select O.ID,  
		  O.ParentID,  
		  D.TextPath as [Path],  
		  D.TypeName as LevelName,  
		  D.Url as Url,  
		  1 as [Level]  
		from [Taxonomy] O  
		 cross apply [utility].[ObjectDetail](@Type,O.ID) as D  
		where O.ID = @ID  
		union all  
		select O.ID,  
		  O.ParentID,  
		  D.TextPath as [Path], 
		  D.TypeName as LevelName,
		  D.Url as Url,   
		  C.[Level] + 1 as [Level]  
		from [Taxonomy] O  
		  inner join Sub as C on C.ParentID = O.ID  
		   cross apply [utility].[ObjectDetail](@Type,O.ID) as D  
	   )  
	  select ID, ParentID,[Path],LevelName,Url,rank() over (Order by Level desc) as [Level] from Sub;
  end
  else if @Type = 'FusionAttribute'   
  begin  
	   with Sub as (  
		select O.ID,  
		  O.ParentID,  
		  D.TextPath as [Path],  
		  D.TypeName as LevelName,  
		  D.Url as Url,  
		  1 as [Level]  
		from FusionAttribute O  
		 cross apply [utility].[ObjectDetail](@Type,O.ID) as D  
		where O.ID = @ID  
		union all  
		select O.ID,  
		  O.ParentID,  
		  D.TextPath as TextPath, 
		  D.TypeName as LevelName,
		  D.Url as Url,   
		  C.[Level] + 1 as [Level]  
		from FusionAttribute O  
		  inner join Sub as C on C.ParentID = O.ID  
		   cross apply [utility].[ObjectDetail](@Type,O.ID) as D  
	   )  
	  select ID, ParentID,[Path],LevelName,Url,rank() over (Order by Level desc) as [Level] from Sub;
  end
  end
