CREATE PROCEDURE [dbo].[Workflow_Task_CheckAndSetGdprFlag]
--declare
	@objectType varchar(50),-- = 'Intersect',
	@objectId int-- = 17 --2
as
begin
	SET NOCOUNT ON;

	declare @st varchar(50),				--Subject Type
			@stid int,						--Subject Type ID
			@s varchar(50),					--Subject
			@sid int,						--Subject ID
			@ot varchar(50),				--Object Type
			@otid int,						--Object Type ID
			@o varchar(50),					--Object
			@oid int,						--Object ID
			@it int,						--Intersect Type ID
			@btPIIFieldTypeID int = null,	--Check to see if the business term artifact type has a PII Flag field
			@btIsPII bit = 0,				--Determine if the current business term is PII
			@targetPDFieldTypeID int = null,--Check to see if the opposite side artifact type has a Personal Data Flag field
			@targetAlreadyIsPD bit = 0,		--Determine is the target's Personal Data is field already marked as active? If not, then go ahead and mark it as active.
			@btIsSubject bit = 0

	if @objectType = 'Intersect'
	begin
		select	@it = T.ID,
				@st = T.Subject,	@stid = T.SubjectID,	@ot = T.Object,		@otid = T.ObjectID,
				@s = I.Subject,		@sid = I.SubjectID,		@o = I.Object,		@oid = I.ObjectID
		from	[Intersect] I
				inner join IntersectType T on T.ID = I.IntersectTypeID and I.ID = @objectId

		set @btIsSubject = case 
			when @st = 'ArtifactType' and @stid = 1 then 1	--1 => Business Term
			else 0
		end

		select @btPIIFieldTypeID =	ID 
		from	FieldType 
		where	( (@btIsSubject = 1 and Object = @st and ObjectID = @stid) or (@btIsSubject = 0 and Object = @ot and ObjectID = @otid) )  and Name = 'PersonalDataFlag' --PIIFlag

		if @btPIIFieldTypeID is not null
		begin
			select @targetPDFieldTypeID  =	ID 
			from FieldType 
			where	( (@btIsSubject = 1 and Object = @ot and ObjectID = @otid) or (@btIsSubject = 0 and Object = @st and ObjectID = @stid) ) and Name = 'ContainPersonalData' --hasPersonalDataFlag
		end

		--select @btPIIFieldTypeID, @targetPDFieldTypeID

		if @btPIIFieldTypeID is not null
		begin
			select	@btIsPII = case lower(Value) when 'true' then 1 else 0 end
			from	Field
			where	( (@btIsSubject = 1 and ObjectType = @s and ObjectID = @sid) or (@btIsSubject = 0 and ObjectType = @o and ObjectID = @oid) )  and FieldTypeID = @btPIIFieldTypeID
		end

		--select @btIsPII

		if @btIsPII = 1
		begin
			select	@targetAlreadyIsPD = case lower(Value) when 'true' then 1 else 0 end
			from	Field
			where	( (@btIsSubject = 1 and ObjectType = @o and ObjectID = @oid) or (@btIsSubject = 0 and ObjectType = @s and ObjectID = @sid) )  and FieldTypeID = @targetPDFieldTypeID			
		end

		--select @targetAlreadyIsPD

		if @btIsPII = 1 and @targetAlreadyIsPD = 0
		begin
			--Finally, we can set the value.
			declare @fo varchar(50) = case when @btIsSubject = 1 then @o else @s end, 
					@foid int = case when @btIsSubject = 1 then @oid else @sid end,
					@fot varchar(50) = case when @btIsSubject = 1 then @ot else @st end, 
					@fotid int = case when @btIsSubject = 1 then @otid else @stid end

			merge into Field as T
			using (VALUES (@fo, @foid, @targetPDFieldTypeID, 'True')) as S (ObjectType, ObjectID, FieldTypeID, Value)  
			on T.ObjectType = S.ObjectType and T.ObjectID = S.ObjectID and T.FieldTypeID = S.FieldTypeID
			when matched then
			update set	Value = S.Value, 
						FormattedValue = S.Value
			when not matched by target then
			insert (ObjectType, ObjectID, FieldTypeID, Value, FormattedValue) values (S.ObjectType, S.ObjectID, S.FieldTypeID, S.Value, S.Value);

			--Now, queue up a change event to send to topic.
			INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID]) 
			values (
				'EventTopicNotification', 
				'<fields><ChangeType>Update</ChangeType><ObjectType>' + @fot + '</ObjectType><ObjectTypeID>' + cast(@fotid as varchar) + '</ObjectTypeID></fields>', 
				@fo, 
				@foid
			);
		end
	end
end
GO
