	--			TT.FormattedValue as TargetFusionAttributeTypeID
	--from		FusionAttribute MA
	--			inner join FieldWithRelation ST on ST.ObjectType = 'FusionAttribute' and ST.ObjectID = MA.ID and ST.Name = 'SourceTypeID'
