	--insert into IntersectType (Subject, SubjectID, Object, ObjectID, IsSystem, State,PredicateID, SubjectCardinality,ObjectCardinality) values ('FusionAttributeType', 1492, 'FusionAttributeType', 1490, 1, 1, 10, 2,2)

