	ON [dbo].[Favorite]
	FOR DELETE
AS

	--update sortorder
	update f
	set f.sortorder = s.sortorder 
	from
		favorite f
		join (
		select 
			id, 
			resourceid, 
			row_number() over (partition by resourceid order by sortorder) as sortorder
		from favorite) s on s.id = f.id
		join deleted i on i.ResourceID = s.ResourceID;
