CREATE TRIGGER [dbo].[ResponsibilityTypeRelationOverrideItem_AfterDelete]
   ON  [dbo].[ResponsibilityTypeRelationOverrideItem]
   AFTER DELETE
AS 
BEGIN
	SET NOCOUNT ON;

	delete	T
	from	ResponsibilityTypeRelationRuleResult T
			inner join deleted S on T.RuleID = 0 and T.OverrideID = S.ID;

	update	T
	set		T.Overridden = 0,
			T.OverrideID = 0
	from	ResponsibilityTypeRelationRuleResult T
			inner join deleted S on T.RuleID <> 0 and T.OverrideID = S.ID;
END
GO
