CREATE TRIGGER [dbo].[SiteNav_AfterDelete]
	ON [dbo].[SiteNav]
	FOR DELETE
AS

	--update sortorder
	update n
	set n.sortorder = s.sortorder 
	from
		sitenav n
		join (
		select 
			id,
			row_number() over (partition by parentid order by sortorder) as sortorder
		from sitenav where parentid is null) s on s.id = n.id;
GO
